"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[21885],{17021:e=>{e.exports=JSON.parse('{"tag":{"label":"middlewares","permalink":"/tags/middlewares","allTagsPath":"/tags","count":14,"items":[{"id":"cms/backend-customization","title":"Back-end customization","description":"All elements of Strapi\'s back end, like routes, policies, middlewares, controllers, services, models, requests, responses, and webhooks, can be customized.","permalink":"/cms/backend-customization"},{"id":"cms/migration/v4-to-v5/breaking-changes/default-index-removed","title":"defaultIndex removed","description":"In Strapi 5, the \'defaultIndex\' option is removed from the \'public\' middleware.","permalink":"/cms/migration/v4-to-v5/breaking-changes/default-index-removed"},{"id":"cms/migration/v4-to-v5/breaking-changes/do-not-update-repeatable-components-with-document-service-api","title":"defaultIndex removed","description":"In Strapi 5, it\'s not recommended to update repeatable components with the Document Service API","permalink":"/cms/migration/v4-to-v5/breaking-changes/do-not-update-repeatable-components-with-document-service-api"},{"id":"cms/error-handling","title":"Error handling","description":"With Strapi\'s error handling feature it\'s easy to send and receive errors in your application.","permalink":"/cms/error-handling"},{"id":"cms/plugins/graphql","title":"GraphQL plugin","description":"Use a GraphQL endpoint in your Strapi project to fetch and mutate your content.","permalink":"/cms/plugins/graphql"},{"id":"cms/backend-customization/middlewares","title":"Middlewares","description":"Middlewares alter the request or response flow at application or API levels. This documentation distinguishes global versus route middlewares and illustrates custom implementations with generation patterns.","permalink":"/cms/backend-customization/middlewares"},{"id":"cms/configurations/middlewares","title":"Middlewares configuration","description":"Strapi offers a single entry point file for its middlewares configurations.","permalink":"/cms/configurations/middlewares"},{"id":"cms/plugins-development/plugins-extension","title":"Plugins extension","description":"Existing plugins can be overriden by placing code in /src/extensions or using global register/bootstrap hooks. Instructions in this documentation cover reshaping plugin content-type schemas or server logic \u2014 altough upstream updates may break extensions.","permalink":"/cms/plugins-development/plugins-extension"},{"id":"cms/backend-customization/policies","title":"Policies","description":"Strapi policies are functions that execute specific logic on each request before it reaches the controller. Policies can be customized according to your needs.","permalink":"/cms/backend-customization/policies"},{"id":"cms/backend-customization/routes","title":"Routes","description":"Strapi routes handle requests to your content and are auto-generated for your content-types. Routes can be customized according to your needs.","permalink":"/cms/backend-customization/routes"},{"id":"cms/plugins-development/server-api","title":"Server API for plugins","description":"Overview of the Strapi Server API for plugins, with entry file, lifecycle hooks, routes, controllers, services, policies, middlewares, and configuration.","permalink":"/cms/plugins-development/server-api"},{"id":"cms/migration/v4-to-v5/breaking-changes/server-default-log-level","title":"Server log level is `http`","description":"The default log level of the middleware logger in Strapi 5 is \'http\'.","permalink":"/cms/migration/v4-to-v5/breaking-changes/server-default-log-level"},{"id":"cms/plugins-development/server-policies-middlewares","title":"Server policies & middlewares","description":"Guard plugin routes with policies and intercept requests with middlewares in the Strapi plugin Server API.","permalink":"/cms/plugins-development/server-policies-middlewares"},{"id":"cloud/advanced/upload","title":"Upload Provider Configuration for Strapi Cloud","description":"Configure Strapi Cloud to use a third-party upload provider.","permalink":"/cloud/advanced/upload"}],"unlisted":false}}')}}]);